(57, 'Matthew Thomas', 'Energy Analyst', 'Student analyst studying mechanical engineering and has worked at the OSU Energy Efficiency Center for over three years.', '/uploads/user_57/d605dc5302d2f31ff9e73921fb796252.png', 10, 1),
(58, 'Ryan French', 'Energy Analyst', 'Undergraduate Physics Student\nCurator for Refrigeration Industry Page', 'https://eec.oregonstate.edu/sites/eec.oregonstate.edu/files/ryan_0.jpg', 10, 1),
