(1614, 198, 15217, 136, 0, 0, 3, '14,500 Btu/hr per ton produced is rejected in the condensers', '', '', 0, 0, 0, 0, '2021-02-09 20:45:14'),
(1615, 199, 15243, 137, 0, 0, 8, '<p>Phone applications with refrigerant tables are a handy aid in evaluating refrigeration systems. </p>', '', '', 0, 0, 0, 0, '2021-02-09 20:49:53'),
